import {
  computeCacheBustingSearchParam,
  computeLegacyCacheBustingSearchParam,
} from '../../../shared/lib/router/utils/cache-busting-search-param'
import {
  NEXT_ROUTER_PREFETCH_HEADER,
  NEXT_ROUTER_SEGMENT_PREFETCH_HEADER,
  NEXT_ROUTER_STATE_TREE_HEADER,
  NEXT_URL,
  NEXT_RSC_UNION_QUERY,
} from '../app-router-headers'
import type { RequestHeaders } from './fetch-server-response'

async function computeClientCacheBustingSearchParam(
  headers: RequestHeaders
): Promise<string> {
  if (typeof globalThis.crypto?.subtle?.digest === 'function') {
    return computeCacheBustingSearchParam(
      headers[NEXT_ROUTER_PREFETCH_HEADER],
      headers[NEXT_ROUTER_SEGMENT_PREFETCH_HEADER],
      headers[NEXT_ROUTER_STATE_TREE_HEADER],
      headers[NEXT_URL]
    )
  }

  return computeLegacyCacheBustingSearchParam(
    headers[NEXT_ROUTER_PREFETCH_HEADER],
    headers[NEXT_ROUTER_SEGMENT_PREFETCH_HEADER],
    headers[NEXT_ROUTER_STATE_TREE_HEADER],
    headers[NEXT_URL]
  )
}

/**
 * Mutates the provided URL by adding a cache-busting search parameter for CDNs that don't
 * support custom headers. This helps avoid caching conflicts by making each request unique.
 *
 * Rather than relying on the Vary header which some CDNs ignore, we append a search param
 * to create a unique URL that forces a fresh request.
 *
 * Example:
 * URL before: https://example.com/path?query=1
 * URL after: https://example.com/path?query=1&_rsc=abc123
 *
 * Note: This function mutates the input URL directly and resolves once the
 * cache-busting value has been computed and applied.
 *
 * TODO: Since we need to use a search param anyway, we could simplify by removing the custom
 * headers approach entirely and just use search params.
 */
export const setCacheBustingSearchParam = async (
  url: URL,
  headers: RequestHeaders
): Promise<void> => {
  const uniqueCacheKey = await computeClientCacheBustingSearchParam(headers)
  setCacheBustingSearchParamWithHash(url, uniqueCacheKey)
}

/**
 * Sets a cache-busting search parameter on a URL using a provided hash value.
 *
 * This function performs the same logic as `setCacheBustingSearchParam` but accepts
 * a pre-computed hash instead of computing it from headers.
 *
 * Example:
 * URL before: https://example.com/path?query=1
 * hash: "abc123"
 * URL after: https://example.com/path?query=1&_rsc=abc123
 *
 * If the hash is empty, we will set `_rsc` search param without a value.
 * Like this: https://example.com/path?query=1&_rsc
 *
 * Note: This function mutates the input URL directly and does not return anything.
 */
export const setCacheBustingSearchParamWithHash = (
  url: URL,
  hash: string
): void => {
  /**
   * Note that we intentionally do not use `url.searchParams.set` here:
   *
   * const url = new URL('https://example.com/search?q=custom%20spacing');
   * url.searchParams.set('_rsc', 'abc123');
   * console.log(url.toString()); // Outputs: https://example.com/search?q=custom+spacing&_rsc=abc123
   *                                                                             ^ <--- this is causing confusion
   * This is in fact intended based on https://url.spec.whatwg.org/#interface-urlsearchparams, but
   * we want to preserve the %20 as %20 if that's what the user passed in, hence the custom
   * logic below.
   */
  const existingSearch = url.search
  const rawQuery = existingSearch.startsWith('?')
    ? existingSearch.slice(1)
    : existingSearch

  // Always remove any existing cache busting param and add a fresh one to ensure
  // we have the correct value based on current request headers
  const pairs = rawQuery
    .split('&')
    .filter((pair) => pair && !pair.startsWith(`${NEXT_RSC_UNION_QUERY}=`))

  if (hash.length > 0) {
    pairs.push(`${NEXT_RSC_UNION_QUERY}=${hash}`)
  } else {
    pairs.push(`${NEXT_RSC_UNION_QUERY}`)
  }
  url.search = pairs.length ? `?${pairs.join('&')}` : ''
}
import type {
  FlightRouterState,
  Segment,
} from '../../shared/lib/app-router-types'
import {
  DEFAULT_SEGMENT_KEY,
  isGroupSegment,
  NOT_FOUND_SEGMENT_KEY,
} from '../../shared/lib/segment'
import { segmentToSourcePagePathname } from './router-reducer/compute-changed-path'
import type {
  ClientInstrumentationHooks,
  ClientInstrumentationModules,
  RouterTransitionPrefetchIntent,
  RouterTransitionType,
} from '../router-transition-types'

let instrumentationModules: readonly ClientInstrumentationHooks[] = []
let nextTransitionId = 0

export function initializeRouterTransitionModules(
  modules: ClientInstrumentationModules
): void {
  instrumentationModules = modules.filter(
    (module): module is ClientInstrumentationHooks => module != null
  )
}

function callHooks(invoke: (hooks: ClientInstrumentationHooks) => void): void {
  for (const hooks of instrumentationModules) {
    try {
      invoke(hooks)
    } catch (error) {
      console.error(
        'An instrumentation-client router transition hook failed',
        error
      )
    }
  }
}

function timestamp(): number {
  return performance.timeOrigin + performance.now()
}

export function startRouterTransition(
  url: string,
  type: RouterTransitionType,
  fromTree: FlightRouterState,
  prefetchIntent: RouterTransitionPrefetchIntent | null
): void {
  // Positive flag check so the instrumentation-only path is removed by DCE when disabled.
  if (process.env.__NEXT_INSTRUMENTATION_CLIENT_ROUTER_TRANSITION_EVENTS) {
    if (
      !instrumentationModules.some(
        (hooks) => typeof hooks.onRouterTransitionStart === 'function'
      )
    ) {
      return
    }

    const id = `${Date.now().toString(36)}-${(++nextTransitionId).toString(36)}`

    callHooks((hooks) =>
      hooks.onRouterTransitionStart?.(url, type, {
        id,
        timestamp: timestamp(),
        fromRoutes: getActiveRoutePaths(fromTree),
        prefetchIntent,
      })
    )
  } else {
    callHooks((hooks) => hooks.onRouterTransitionStart?.(url, type, null))
  }
}

function classifySegment(segment: Segment): {
  path: string | null
  isPage: boolean
} {
  const sourceSegment = segmentToSourcePagePathname(segment)
  if (sourceSegment === 'page') {
    return { path: null, isPage: true }
  }
  if (
    sourceSegment === '' ||
    sourceSegment === '(__SLOT__)' ||
    isGroupSegment(sourceSegment)
  ) {
    return { path: null, isPage: false }
  }
  if (sourceSegment === DEFAULT_SEGMENT_KEY) {
    return { path: 'default', isPage: false }
  }
  if (sourceSegment === NOT_FOUND_SEGMENT_KEY) {
    return { path: '_not-found', isPage: false }
  }
  return { path: sourceSegment, isPage: false }
}

function getActiveRoutePaths(tree: FlightRouterState): string[] {
  const routes: Array<{ path: string; primary: boolean }> = []

  function visit(
    node: FlightRouterState,
    segments: string[],
    primary: boolean
  ): void {
    const segment = classifySegment(node[0])
    const nextSegments =
      segment.path === null ? segments : [...segments, segment.path]
    const parallelRoutes = node[1]
    const keys = Object.keys(parallelRoutes)

    if (keys.length === 0 || segment.isPage) {
      routes.push({
        path: `/${nextSegments.join('/')}`,
        primary,
      })
      return
    }

    if (parallelRoutes.children !== undefined) {
      visit(parallelRoutes.children, nextSegments, primary)
    }

    for (const key of keys.sort()) {
      if (key === 'children') {
        continue
      }
      visit(parallelRoutes[key], [...nextSegments, `@${key}`], false)
    }
  }

  visit(tree, [], true)
  return routes
    .sort((a, b) => {
      if (a.primary !== b.primary) {
        return a.primary ? -1 : 1
      }
      return a.path.localeCompare(b.path)
    })
    .map((route) => route.path)
}
