} from './cache'
import {
  EntryStatus,
  writeRouteIntoCache,
  fulfillRouteCacheEntry,
  getCurrentRouteCacheVersion,
  type PendingRouteCacheEntry,
  createMetadataRouteTree,
  createRootRouteTree,
  getHeadRequestKey,
} from './cache'
import { isValueExpired } from './cache-map'
import {
